CREATE TABLE tenant_messaging_policies(tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,timezone text NOT NULL DEFAULT 'Asia/Kuala_Lumpur',quiet_start_minute integer NOT NULL DEFAULT 1320 CHECK(quiet_start_minute BETWEEN 0 AND 1439),quiet_end_minute integer NOT NULL DEFAULT 480 CHECK(quiet_end_minute BETWEEN 0 AND 1439),allowed_weekdays smallint[] NOT NULL DEFAULT ARRAY[0,1,2,3,4,5,6]::smallint[],marketing_enabled boolean NOT NULL DEFAULT true,transactional_enabled boolean NOT NULL DEFAULT true,max_messages_per_minute integer NOT NULL DEFAULT 30 CHECK(max_messages_per_minute BETWEEN 1 AND 1000),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_channel_preferences(tenant_id uuid NOT NULL,customer_id uuid NOT NULL,whatsapp_enabled boolean NOT NULL DEFAULT true,marketing_opt_in boolean NOT NULL DEFAULT false,opted_out_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,customer_id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE messaging_policy_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,customer_id uuid,automation_job_id uuid,decision text NOT NULL CHECK(decision IN('ALLOW','DEFER','BLOCK')),reason text NOT NULL,next_attempt_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE SET NULL,FOREIGN KEY(automation_job_id) REFERENCES automation_jobs(id) ON DELETE SET NULL);
CREATE INDEX messaging_policy_audit_tenant_time_idx ON messaging_policy_audit(tenant_id,created_at DESC);
